import { createServer, type Server } from "node:http";
import { appendFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const REDIRECT_PORT = 7734;
const REDIRECT_URI = `http://localhost:${REDIRECT_PORT}/callback`;
const TWITCH_TOKEN = "https://id.twitch.tv/oauth2/token";
const TWITCH_VALIDATE = "https://id.twitch.tv/oauth2/validate";

const DEBUG_FILE = join(homedir(), "Desktop", "ratpack-debug.txt");
function dbg(msg: string) { try { appendFileSync(DEBUG_FILE, `[${new Date().toISOString()}] oauth: ${msg}\n`); } catch { /**/ } }

// Guard: only one callback server at a time
let activeServer: Server | null = null;

export interface TwitchTokens {
	accessToken: string;
	refreshToken: string;
	expiresAt: number; // ms timestamp
	userId: string;
	username: string;
}

/**
 * Start the OAuth callback server using PKCE params already generated by the PI.
 * The browser is opened by the PI directly; this function only handles the redirect.
 */
export async function startOAuthCallbackServer(
	clientId: string,
	clientSecret: string,
	verifier: string,
	state: string,
): Promise<TwitchTokens> {
	// Close any previous server (handles double-click on Connect)
	if (activeServer) {
		try { activeServer.close(); } catch { /**/ }
		activeServer = null;
	}

	return new Promise((resolve, reject) => {
		const timeout = setTimeout(() => {
			server.close();
			activeServer = null;
			reject(new Error("OAuth timeout"));
		}, 300_000);

		const done = (fn: () => void) => {
			clearTimeout(timeout);
			server.close();
			activeServer = null;
			fn();
		};

		const server = createServer(async (req, res) => {
			const url = new URL(req.url ?? "/", `http://localhost:${REDIRECT_PORT}`);
			if (url.pathname !== "/callback") { res.end("Not found"); return; }

			const code = url.searchParams.get("code");
			const returnedState = url.searchParams.get("state");
			dbg(`callback: state_match=${returnedState === state} has_code=${!!code}`);

			if (returnedState !== state || !code) {
				res.writeHead(400);
				res.end("OAuth state mismatch — please try again.");
				done(() => reject(new Error("OAuth state mismatch")));
				return;
			}

			try {
				dbg(`fetching token for code=${code.slice(0, 8)}... verifier_len=${verifier.length}`);
				const tokenRes = await fetch(TWITCH_TOKEN, {
					method: "POST",
					headers: { "Content-Type": "application/x-www-form-urlencoded" },
					body: (() => {
						const p = new URLSearchParams({ client_id: clientId, code, grant_type: "authorization_code", redirect_uri: REDIRECT_URI, code_verifier: verifier });
						if (clientSecret) p.set("client_secret", clientSecret);
						return p;
					})(),
				});

				const rawBody = await tokenRes.text();
				dbg(`token response ${tokenRes.status}: ${rawBody}`);

				const tokenData = JSON.parse(rawBody) as {
					access_token?: string;
					refresh_token?: string;
					expires_in?: number;
					error?: string;
					message?: string;
					status?: number;
				};

				if (!tokenData.access_token) {
					const errMsg = tokenData.message ?? tokenData.error ?? "No access token";
					throw new Error(`Twitch ${tokenRes.status}: ${errMsg}`);
				}

				const validateRes = await fetch(TWITCH_VALIDATE, {
					headers: { Authorization: `OAuth ${tokenData.access_token}` },
				});
				const validateData = (await validateRes.json()) as { user_id?: string; login?: string };

				const tokens: TwitchTokens = {
					accessToken: tokenData.access_token,
					refreshToken: tokenData.refresh_token ?? "",
					expiresAt: Date.now() + (tokenData.expires_in ?? 86400) * 1000,
					userId: validateData.user_id ?? "",
					username: validateData.login ?? "",
				};

				dbg(`auth success: user=${tokens.username}`);
				res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
				res.end(`<html><meta charset="utf-8"><body style="font-family:sans-serif;background:#0d0d14;color:#fff;text-align:center;padding:60px">
					<h2 style="color:#9146FF">&#10003; Connected to Twitch!</h2>
					<p>You can close this window and return to Stream Deck.</p>
				</body></html>`);

				done(() => resolve(tokens));
			} catch (err) {
				const errStr = String(err instanceof Error ? err.message : err);
				dbg(`token exchange failed: ${errStr}`);
				res.writeHead(500, { "Content-Type": "text/html" });
				res.end(`<html><body style="font-family:sans-serif;background:#0d0d14;color:#fff;padding:40px">
					<h2 style="color:#f66">Authorization failed</h2>
					<pre style="background:#111;padding:16px;border-radius:8px;text-align:left;white-space:pre-wrap">${errStr}</pre>
					<p style="color:#aaa">Close this window and try again.</p>
				</body></html>`);
				done(() => reject(new Error(errStr)));
			}
		});

		activeServer = server;
		server.listen(REDIRECT_PORT);
		server.on("error", (err) => { done(() => reject(err)); });
	});
}

/** Refresh an expired Twitch access token using the stored refresh token. */
export async function refreshTwitchToken(clientId: string, refreshToken: string, clientSecret?: string): Promise<TwitchTokens> {
	const res = await fetch(TWITCH_TOKEN, {
		method: "POST",
		headers: { "Content-Type": "application/x-www-form-urlencoded" },
		body: (() => {
			const p = new URLSearchParams({ client_id: clientId, grant_type: "refresh_token", refresh_token: refreshToken });
			if (clientSecret) p.set("client_secret", clientSecret);
			return p;
		})(),
	});

	const data = (await res.json()) as {
		access_token?: string;
		refresh_token?: string;
		expires_in?: number;
		error?: string;
	};

	if (!data.access_token) throw new Error(data.error ?? "Token refresh failed");

	const validateRes = await fetch(TWITCH_VALIDATE, {
		headers: { Authorization: `OAuth ${data.access_token}` },
	});
	const vd = (await validateRes.json()) as { user_id?: string; login?: string };

	return {
		accessToken: data.access_token,
		refreshToken: data.refresh_token ?? refreshToken,
		expiresAt: Date.now() + (data.expires_in ?? 86400) * 1000,
		userId: vd.user_id ?? "",
		username: vd.login ?? "",
	};
}
